import numpy as np


def generator(z, W, b):
    return z @ W + b


def bce(pred, target):
    p = np.clip(pred, 1e-7, 1 - 1e-7)
    return -np.mean(target * np.log(p) + (1 - target) * np.log(1 - p))


def discriminator_loss(d_real, d_fake):
    return bce(d_real, np.ones_like(d_real)) + bce(d_fake, np.zeros_like(d_fake))


def generator_loss(d_fake):
    return bce(d_fake, np.ones_like(d_fake))


rng = np.random.default_rng(0)
z = rng.standard_normal((5, 2))                       # 5 noise vectors
W, b = rng.standard_normal((2, 2)), np.zeros(2)
fake_points = generator(z, W, b)
print("fake points shape:", np.shape(fake_points))

d_real = np.array([0.9, 0.8, 0.95])    # D's belief that real points are real
d_fake = np.array([0.1, 0.2, 0.05])    # D's belief that fake points are real
print("D loss:", None if discriminator_loss(d_real, d_fake) is None else round(float(discriminator_loss(d_real, d_fake)), 4))
print("G loss:", None if generator_loss(d_fake) is None else round(float(generator_loss(d_fake)), 4))
